-- Bancada descartável. Nenhuma mensagem, nenhuma chamada de rede; rollback integral.
begin;
create temporary table d4 as select gen_random_uuid() shop,gen_random_uuid() person,gen_random_uuid() a,gen_random_uuid() b,gen_random_uuid() plan,gen_random_uuid() grp,gen_random_uuid() cycle,null::jsonb job,null::jsonb body,null::jsonb step;
create function pg_temp.check_d4(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end $$;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select pg_temp.check_d4((select not enabled from public.whatsapp_care_cycle_policy),'Contrato novo não herda liberação do piloto anterior');
update public.whatsapp_send_controls set paused=false where scope='global';
update d4 set shop=(public.register_my_barbershop(gen_random_uuid(),'Ciclo Fictício','America/Sao_Paulo','single',true,'teste','teste','teste')->>'shop_id')::uuid;
select public.platform_create_whatsapp_channel(a,'Ciclo A') from d4;
select public.platform_create_whatsapp_channel(b,'Ciclo B') from d4;
update public.whatsapp_channels set display_phone=case id when (select a from d4) then '+5511800000111' else '+5511800000222' end,status='open' where id in(select a from d4 union all select b from d4);
select public.platform_confirm_whatsapp_control(id,routing_version,display_phone,instance_name,true) from public.whatsapp_channels where id in(select a from d4 union all select b from d4);
select public.platform_plan_whatsapp_distribution(plan,array[shop],false) from d4;
select public.platform_apply_whatsapp_distribution(plan) from d4;
-- Rota explícita da fixture: outros ensaios podem conservar números com a mesma identidade.
select public.platform_set_whatsapp_route(d.shop,null,(select version from public.whatsapp_number_links where barbershop_id=d.shop and staff_id is null and removed_at is null),d.a,d.b,null,'primary',false,false,false) from d4 d;
select pg_temp.check_d4((select jsonb_array_length(public.care_cycle_composition(shop))=2 from d4),'Composição da loja usa dois telefones físicos com controle confirmado');
insert into auth.users(id,email,raw_user_meta_data) select person,person||'@example.invalid','{}' from d4;
insert into public.memberships(user_id,barbershop_id,role) select person,shop,'customer' from d4;

create function pg_temp.denied(query text,expected text,label text) returns void language plpgsql as $$begin
 begin execute query;raise exception 'FAIL: %',label;exception when others then
 if sqlerrm like 'FAIL:%' or sqlerrm<>expected then raise;end if;raise notice 'PASS: %',label;end;
end $$;
create temporary table access_test(id uuid,job jsonb,expires_at timestamptz,cycle uuid,enrollment timestamptz);
insert into access_test values(null,null,null,null,null);
select pg_temp.check_d4((select not assisted_access_enabled from public.whatsapp_care_cycle_policy),'Acompanhamento nasce desligado sem ligar piloto');
select set_config('request.jwt.claim.sub',(select person::text from d4),true);
select pg_temp.denied(format('select public.care_access_start(%L,%L,array[%L,%L]::uuid[],true)',shop,'+5511998888777',a,b),'GROUP_UNAVAILABLE','Política desligada impede nova intenção') from d4;
update public.whatsapp_care_cycle_policy set enabled=true,assisted_access_enabled=true where singleton;
select pg_temp.denied(format('select public.care_access_start(%L,%L,array[%L,%L]::uuid[],false)',shop,'+5511998888777',a,b),'GROUP_UNAVAILABLE','Sem aceite explícito não inicia') from d4;
update public.whatsapp_channels set connection_observed_at=clock_timestamp()-interval '1 day' where id in(select a from d4 union all select b from d4);
update access_test set id=(select public.care_access_start(shop,'+5511998888777',array[a,b],true) from d4);
select pg_temp.check_d4((select count(*)=0 from public.whatsapp_care_cycles where group_id in(select id from public.whatsapp_care_groups where customer_id=(select person from d4))),'Aceite com conexão antiga só abre intenção; não cria grupo/ciclo');
select pg_temp.check_d4((select count(*)=0 from public.whatsapp_send_attempts where activity_group_id in(select id from public.whatsapp_care_groups where customer_id=(select person from d4))),'Abrir intenção não solicita código nem envia mensagem');
update access_test set expires_at=(select expires_at from public.whatsapp_care_access where id=access_test.id);
select pg_temp.check_d4((select id=(select public.care_access_start(shop,'+5511998888777',array[a,b],true) from d4) from access_test),'Clique repetido usa mesma intenção');
select pg_temp.check_d4((select a.expires_at=t.expires_at from public.whatsapp_care_access a,access_test t where a.id=t.id),'Repetir clique não estende janela automaticamente');
update access_test set job=(select public.claim_care_access(person,shop) from d4);
select pg_temp.check_d4((select jsonb_array_length(job->'targets')=2 and job->>'token' is not null from access_test),'Serviço obtém apenas dois números consentidos e posse temporária');
select pg_temp.check_d4((select public.claim_care_access(person,shop)->>'waiting'='true' from d4),'Segunda aba não executa a mesma etapa simultaneamente');
select pg_temp.check_d4((select public.claim_care_access(gen_random_uuid(),shop) is null from d4),'Outra conta não obtém intenção do titular');
select pg_temp.denied(format('select public.resume_care_access(%L,%L)',id,job->>'token'),'GROUP_PARTICIPANTS_CHANGED','Retomar ainda exige conexão real recente') from access_test;
select pg_temp.denied(format('select public.resume_care_access(%L,%L)',id,gen_random_uuid()),'GROUP_STALE','Posse incorreta não retoma nem cria grupo') from access_test;
select pg_temp.denied(format('select public.record_care_access_connections(%L,%L,%L,%L::jsonb)',id,(select person from d4),job->>'token',jsonb_set((select jsonb_agg(n||jsonb_build_object('status','open','observed_phone',n->>'phone')) from jsonb_array_elements(job->'targets') n),'{0,version}','999999'::jsonb)),'GROUP_STALE','Versão de roteamento alterada recusa observação inteira') from access_test;
select pg_temp.check_d4((select not public.care_cycle_composition_valid(public.care_cycle_composition(shop)) from d4),'Falha CAS não prolonga observação antiga');
select public.record_care_access_connections(id,(select person from d4),(job->>'token')::uuid,(select jsonb_agg(n||jsonb_build_object('status','open','observed_phone',n->>'phone')) from jsonb_array_elements(job->'targets') n)) from access_test;
select pg_temp.check_d4((select public.care_cycle_composition_valid(public.care_cycle_composition(shop)) from d4),'Conferência seletiva renova só prova legítima dos números');
update access_test set cycle=public.resume_care_access(id,(job->>'token')::uuid);
select pg_temp.check_d4((select count(*)=1 from public.whatsapp_care_cycles where group_id in(select id from public.whatsapp_care_groups where customer_id=(select person from d4))),'Conferência seguida do contrato original cria um ciclo apenas');
select pg_temp.check_d4((select not (public.care_group_read(shop)->>'phone_ready')::boolean from d4),'Criação não libera telefone/código sem presença e acolhimento');
select pg_temp.check_d4((select whatsapp_verified_at is null and whatsapp_e164 is null from public.profiles where id=(select person from d4)),'Nenhum telefone de perfil é trocado ou confirmado pela automação');
update access_test set enrollment=(select e.expires_at from public.whatsapp_group_enrollments e join public.whatsapp_care_groups g on g.id=e.group_id where g.current_cycle_id=access_test.cycle);
select pg_temp.check_d4((select public.resume_care_access(id,(job->>'token')::uuid)=cycle from access_test),'Retomada mantém mesmo ciclo/JID e diário');
select pg_temp.check_d4((select e.expires_at=t.enrollment from public.whatsapp_group_enrollments e join public.whatsapp_care_groups g on g.id=e.group_id join access_test t on t.cycle=g.current_cycle_id),'Acompanhamento não renova matrícula a cada consulta');
select pg_temp.denied(format('select public.care_access_start(%L,%L,array[%L,%L]::uuid[],true,%L,%s)',d.shop,'+5511998888778',d.a,d.b,g.id,g.version),'GROUP_PHONE_UNAVAILABLE','Telefone diferente do grupo vai para revisão, sem inferir nono dígito') from d4 d join public.whatsapp_care_groups g on g.barbershop_id=d.shop;
select pg_temp.denied(format('select public.care_access_start(%L,%L,array[%L]::uuid[],true,%L,%s)',d.shop,'+5511998888777',d.a,g.id,g.version),'GROUP_PARTICIPANTS_CHANGED','Não reduz composição para um único admin') from d4 d join public.whatsapp_care_groups g on g.barbershop_id=d.shop;
select public.finish_care_access(id,(select person from d4),(job->>'token')::uuid,false) from access_test;
select pg_temp.check_d4((select public.claim_care_access(person,shop)->>'waiting'='true' from d4),'Intervalo entre conferências vale entre requisições/abas');
update public.whatsapp_care_access set next_at=clock_timestamp()-interval '1 second';
update public.whatsapp_send_controls set paused=true where scope='global';
select pg_temp.check_d4((select public.claim_care_access(person,shop) is null from d4),'Pausa global interrompe acompanhamento antes da Evolution');
select pg_temp.check_d4((select not (public.care_group_read(shop)->>'enabled')::boolean from d4),'Leitura mostra indisponibilidade sob pausa global');
update public.whatsapp_send_controls set paused=false where scope='global';
update public.whatsapp_care_access set expires_at=clock_timestamp()-interval '1 second';
select pg_temp.check_d4((select public.claim_care_access(person,shop) is null from d4),'Janela expirada não se renova em segundo plano');
update public.whatsapp_care_access set expires_at=clock_timestamp()+interval '10 minutes';
update public.profiles set whatsapp_e164='+5511998888778' where id=(select person from d4);
select pg_temp.check_d4((select public.claim_care_access(person,shop) is null from d4),'Mudança do perfil invalida intenção antiga');
update public.profiles set whatsapp_e164=null where id=(select person from d4);
update public.whatsapp_care_cycles set state='creation_unknown' where id=(select cycle from access_test);
select pg_temp.check_d4((select public.claim_care_access(person,shop) is null from d4),'Criação incerta não é recriada pelo acesso assistido');
update public.whatsapp_care_cycles set state='draft' where id=(select cycle from access_test);
update public.whatsapp_care_cycle_policy set enabled=false where singleton;
select pg_temp.check_d4((select public.claim_care_access(person,shop) is null from d4),'Desligar piloto bloqueia janela ainda válida');
select pg_temp.check_d4(not has_table_privilege('authenticated','public.whatsapp_care_access','select'),'Cliente não lê números/telefones de intenções privadas');
select pg_temp.check_d4(not has_table_privilege('service_role','public.whatsapp_care_access','select'),'Serviço usa contratos sem acesso direto à tabela');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.claim_care_access(uuid,uuid)','execute'),'Cliente não obtém posse nem instâncias');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.record_care_access_connections(uuid,uuid,uuid,jsonb)','execute'),'Cliente não forja conexão recente');
select pg_temp.check_d4(not has_function_privilege('authenticated','public.care_group_read_before_assisted(uuid,uuid)','execute'),'Wrapper legado não oferece desvio da pausa');
rollback;
